// _VAL_0_0 = 0.0 in fixed-point Q8.8
localparam logic signed [15:0] _VAL_0_0 = 16'sd0;
// _VAL_5_0 = 5.0 in fixed-point Q8.8
localparam logic signed [15:0] _VAL_5_0 = 16'sd1280;

logic signed [15:0] sva_input_u_in;

