    if (rst) begin
        sva_input_u_in <= 16'sd0;
    end else begin
        sva_input_u_in <= u_in;
    end
end

`ifndef FORMAL
logic [63:0] sva_row;
always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
        sva_row <= 64'd0;
    end else begin
        sva_row <= sva_row + 64'd1;
