// x_in_range (always): always x >= 0 && x <= 5
logic sva_x_in_range_cond;
assign sva_x_in_range_cond = ((state_x >= _VAL_0_0) && (state_x <= _VAL_5_0));
logic sva_x_in_range_failed_now;
assign sva_x_in_range_failed_now = !sva_x_in_range_cond;

// input_never_max (never): never u == 5
logic sva_input_never_max_cond;
assign sva_input_never_max_cond = (sva_input_u_in == _VAL_5_0);
logic sva_input_never_max_failed_now;
assign sva_input_never_max_failed_now = sva_input_never_max_cond;

`ifndef FORMAL
logic sva_x_follows_input_failed;
logic [63:0] sva_x_follows_input_reported_row;
